USE shopping_analysis;

SELECT *
FROM customer_shopping
LIMIT 20;


-- Q1. What is the total revenue generated by male vs. female customers?

SELECT
    gender,
    SUM(`purchase_amount_(usd)`) AS total_revenue
FROM customer_shopping
GROUP BY gender
ORDER BY total_revenue DESC;

-- Q2. Which customers used a discount but still spent more than
-- the average purchase amount?
SELECT
    customer_id,
    gender,
    age,
    item_purchased,
    `purchase_amount_(usd)` AS purchase_amount,
    discount_applied
FROM customer_shopping
WHERE discount_applied = 'Yes'
  AND `purchase_amount_(usd)` > (
      SELECT AVG(`purchase_amount_(usd)`)
      FROM customer_shopping
  )
ORDER BY `purchase_amount_(usd)` DESC;


-- Q3. Which are the top 5 products with the highest average review rating?

SELECT
    item_purchased,
    ROUND(AVG(review_rating), 2) AS average_review_rating,
    COUNT(*) AS total_reviews
FROM customer_shopping
GROUP BY item_purchased
ORDER BY average_review_rating DESC
LIMIT 5;


-- Q5. Do subscribed customers spend more?
-- Compare average spend and total revenue between subscribers and non-subscribers.

SELECT
    subscription_status,
    COUNT(*) AS total_purchases,
    ROUND(AVG(`purchase_amount_(usd)`), 2) AS average_spend,
    SUM(`purchase_amount_(usd)`) AS total_revenue
FROM customer_shopping
GROUP BY subscription_status
ORDER BY total_revenue DESC;


-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

SELECT
    item_purchased,
    COUNT(*) AS total_purchases,

    SUM(
        CASE
            WHEN discount_applied = 'Yes' THEN 1
            ELSE 0
        END
    ) AS discounted_purchases,

    ROUND(
        100.0 * SUM(
            CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        2
    ) AS discount_percentage

FROM customer_shopping
GROUP BY item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;


-- Q7. Segment customers into New, Returning, and Loyal based on their
-- total number of previous purchases, and show the count of each segment.

SELECT
    CASE
        WHEN previous_purchases <= 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 5 THEN 'Returning'
        WHEN previous_purchases > 5 THEN 'Loyal'
    END AS customer_segment,

    COUNT(DISTINCT customer_id) AS customer_count

FROM customer_shopping
GROUP BY customer_segment
ORDER BY
    CASE customer_segment
        WHEN 'New' THEN 1
        WHEN 'Returning' THEN 2
        WHEN 'Loyal' THEN 3
    END;


-- Q7. Segment customers into New, Returning, and Loyal based on previous purchases.
-- New: 1-5 purchases
-- Returning: 6-10 purchases
-- Loyal: More than 10 purchases

SELECT
    CASE
        WHEN previous_purchases BETWEEN 1 AND 5 THEN 'New'
        WHEN previous_purchases BETWEEN 6 AND 10 THEN 'Returning'
        WHEN previous_purchases > 10 THEN 'Loyal'
        ELSE 'Unknown'
    END AS customer_segment,

    COUNT(DISTINCT customer_id) AS customer_count

FROM customer_shopping
GROUP BY customer_segment
ORDER BY
    CASE customer_segment
        WHEN 'New' THEN 1
        WHEN 'Returning' THEN 2
        WHEN 'Loyal' THEN 3
        ELSE 4
    END;


-- Q8. What are the top 3 most purchased products within each category?

WITH product_counts AS (
    -- Step 1: Count purchases of each product within each category
    SELECT
        category,
        item_purchased,
        COUNT(*) AS purchase_count
    FROM customer_shopping
    GROUP BY
        category,
        item_purchased
),

ranked_products AS (
    -- Step 2: Rank products within each category by purchase count
    SELECT
        category,
        item_purchased,
        purchase_count,

        DENSE_RANK() OVER (
            PARTITION BY category
            ORDER BY purchase_count DESC
        ) AS product_rank

    FROM product_counts
)

-- Step 3: Return the top 3 ranked products in every category
SELECT
    category,
    item_purchased,
    purchase_count,
    product_rank
FROM ranked_products
WHERE product_rank <= 3
ORDER BY
    category,
    product_rank;


-- Q9. Are customers who are repeat buyers (more than 5 previous purchases)
-- also likely to subscribe?

SELECT
    CASE
        WHEN previous_purchases > 5 THEN 'Repeat Buyer'
        ELSE 'Other Customers'
    END AS customer_type,

    COUNT(DISTINCT customer_id) AS total_customers,

    COUNT(DISTINCT CASE
        WHEN subscription_status = 'Yes' THEN customer_id
    END) AS subscribed_customers,

    ROUND(
        100.0 * COUNT(DISTINCT CASE
            WHEN subscription_status = 'Yes' THEN customer_id
        END)
        / COUNT(DISTINCT customer_id),
        2
    ) AS subscription_percentage

FROM customer_shopping
GROUP BY customer_type
ORDER BY subscription_percentage DESC;


-- Q10. What is the revenue contribution of each age group?

SELECT
    age_group,

    SUM(`purchase_amount_(usd)`) AS total_revenue,

    ROUND(
        100.0 * SUM(`purchase_amount_(usd)`)
        / SUM(SUM(`purchase_amount_(usd)`)) OVER (),
        2
    ) AS revenue_contribution_percentage

FROM customer_shopping
GROUP BY age_group
ORDER BY total_revenue DESC;
 
 
 USE shopping_analysis;
 SELECT *
FROM customer_shopping;
 



